import math
slope=0.0
def control(obs):
    global slope
    h=obs['hitch_deg']; th=math.radians(-h)
    cam=obs['views'].get('camera')
    if not cam: return (1.6*h,-0.4,-23)
    def point(b,d):
        a=math.radians(b); x=d*math.cos(a); y=d*math.sin(a)
        return (-math.cos(th)*x-math.sin(th)*y,-math.sin(th)*x+math.cos(th)*y)
    corners=sorted(point(b,d) for b,d in cam.get('target_corners',[]))
    error=None
    if len(corners)>=4:
        near=corners[:2]; far=corners[-2:]
        u0=sum(p[0] for p in near)/2; v0=sum(p[1] for p in near)/2
        u1=sum(p[0] for p in far)/2; v1=sum(p[1] for p in far)/2
        if u1-u0>1:
            slope=(v1-v0)/(u1-u0)
            error=v0+slope*(3-u0)
    elif len(corners)==2:
        u=sum(p[0] for p in corners)/2; v=sum(p[1] for p in corners)/2
        error=v+slope*(3-u)
    if error is None:
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            u,v=point(b,d)
            if 0.5<u<6.5: sides[v>0].append((u,v))
        estimates=[]
        for pts in sides:
            if not pts: continue
            pts=sorted(pts,key=lambda p:abs(p[0]-3))[:5]
            w=[1/(0.3+(u-3)**2) for u,v in pts]; sw=sum(w)
            mu=sum(q*p[0] for q,p in zip(w,pts))/sw; mv=sum(q*p[1] for q,p in zip(w,pts))/sw
            den=sum(q*(p[0]-mu)**2 for q,p in zip(w,pts))
            m=sum(q*(p[0]-mu)*(p[1]-mv) for q,p in zip(w,pts))/max(den,0.01)
            estimates.append(mv+m*(3-mu))
        error=sum(estimates)/2 if len(estimates)==2 else 0
    desired=max(-28,min(28,math.degrees(math.atan2(5.2*error,9))))
    steer=max(-34,min(34,2*h-1.3*desired))
    return (steer,-0.45,-23)

